import json

def add_cell(calls, pattern, row, channel, note=None, instrument=None, volume=48, effect=None, effect_param=None):
    # Only add if note or instrument set? We'll always set note and instrument when we want.
    entry = {
        'name':'pattern_set_cell',
        'arguments':{
            'pattern': pattern,
            'row': row,
            'channel': channel,
        }
    }
    if note is not None:
        entry['arguments']['note'] = note
    if instrument is not None:
        entry['arguments']['instrument'] = instrument
    if volume is not None:
        entry['arguments']['volume'] = volume
    if effect is not None:
        entry['arguments']['effect'] = effect
        entry['arguments']['effect_param'] = effect_param
    calls.append(entry)

calls = []

# Patterns 0-3
patterns = 4
channels = [0,1,2,3,4,5]  # lead, bass, kick, snare, hihat, lead2

# Instrument mapping
instr_lead = 1
instr_bass = 2
instr_kick = 3
instr_snare = 4
instr_hihat =5

# Helper to set drums
def add_drums(pattern):
    for row in range(64):
        mod16 = row % 16
        # kick
        if mod16 in (0,8):
            add_cell(calls, pattern, row, 2, note=36, instrument=instr_kick, volume=64)
        # snare
        if mod16 in (4,12):
            add_cell(calls, pattern, row, 3, note=48, instrument=instr_snare, volume=64)
        # hihat every 4 rows, offset 2
        if row % 4 == 2:
            add_cell(calls, pattern, row, 4, note=60, instrument=instr_hihat, volume=40)
        # hihat closed also on 6? Let's do 3? Hmm
        if row % 4 == 3:
            add_cell(calls, pattern, row, 4, note=60, instrument=instr_hihat, volume=30)

# Bass pattern same for all? Slight variation
def add_bass(pattern, variation=0):
    for row in range(64):
        mod16 = row % 16
        if mod16 == 0:
            note = 33 + variation  # A2
        elif mod16 == 8:
            note = 40 + variation   # E3
        else:
            continue
        add_cell(calls, pattern, row, 1, note=note, instrument=instr_bass, volume=60)

# Lead melodies
def lead_melody_pattern0(row):
    # arpeggio A C E A per 4 rows
    pattern = [57,60,64,57]
    idx = (row // 4) % 4  # every 4 rows? Hmm
    # actually we want per row
    # use row mod 4
    idx = row % 4
    note = pattern[idx]
    # add variation every 16 rows
    if row //16 %2 ==1:
        # transpose up octave
        note +=12
    return note

def lead_melody_pattern1(row):
    # more movement
    seq = [57,57,60,60,57,57,55,55]  # simple
    # repeat every 8 rows? Let's cycle every 8 rows
    idx = (row //2) % len(seq)  # every 2 rows
    return seq[idx]

def lead_melody_pattern2(row):
    # chorus louder
    seq = [69,64,60,57,64,69,72,69]
    idx = row % len(seq)
    return seq[idx]

def lead_melody_pattern3(row):
    # breakdown
    if row % 8 ==0:
        return 57
    if row %8 ==4:
        return 60
    return None

melodies = [lead_melody_pattern0, lead_melody_pattern1, lead_melody_pattern2, lead_melody_pattern3]

for pat in range(4):
    # drums
    add_drums(pat)
    # bass
    add_bass(pat, variation=0)
    # lead channel 0
    mel = melodies[pat]
    for row in range(64):
        note = mel(row)
        if note is not None:
            # add cell with some volume
            vol = 64 if pat==2 else 56
            add_cell(calls, pat, row, 0, note=note, instrument=instr_lead, volume=vol)
    # harmony channel5 (octave up)
    if pat in (1,2):
        for row in range(64):
            note = mel(row)
            if note is not None and row%4==0:
                add_cell(calls, pat, row, 5, note=note+12, instrument=instr_lead, volume=48)

# set order
order = [0,1,2,3]
for pos, pat in enumerate(order):
    calls.append({
        'name':'order_set',
        'arguments':{'position':pos,'pattern':pat}
    })
# set song length
calls.append({
    'name':'song_set',
    'arguments':{'length': len(order), 'loop_start':0}
})

with open('/workspace/batch_patterns.json','w') as f:
    json.dump(calls,f)
print('calls',len(calls))
PY"}

